def medmcqa_partial_credit_elimination(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, gt in zip(completions, answer):
        text = completion[0]['content']
        thinking = extract_thinking(text) or ''
        pred = extract_solution(text)

        if is_correct(pred, gt):
            scores.append(5.0)
            continue

        # Partial credit for wrong answers based on reasoning quality
        # Check if the model explicitly eliminated options
        eliminated = 0
        for opt in ['A', 'B', 'C', 'D']:
            # Look for patterns like "Option A is incorrect", "A is wrong", "not A"
            if re.search(rf'(Option\s+{opt}|^{opt}\s|\b{opt}\b).{{0,50}}(incorrect|wrong|not|exclude|eliminate|false|impossible)', thinking, re.IGNORECASE | re.MULTILINE):
                eliminated += 1

        # Reward for eliminating at least 1 wrong option
        if eliminated >= 1:
            scores.append(1.0 + eliminated * 0.25)
        else:
            scores.append(-1.0)
    return scores

def medmcqa_explicit_penalty_wrong_format(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, gt in zip(completions, answer):
        text = completion[0]['content']
        m = re.search(r'<solution>(.*?)</solution>', text, re.DOTALL)
        if not m:
            scores.append(-2.0)
            continue

        sol_text = m.group(1).strip()
        if re.fullmatch(r'[A-D]', sol_text):
            scores.append(0.0)
        else:
            # Heavy penalty for non-standard format
            scores.append(-1.5)
    return scores

def medmcqa_group_relative_length(prompts, completions, answer, **kwargs):
    import math
    groups = {}
    for i, p in enumerate(prompts):
        groups.setdefault(str(p[-1]['content']), []).append(i)

    scores = [0.0] * len(completions)
    for idx in groups.values():
        if len(idx) < 2:
            continue
        lens = [len(completions[i][0]['content']) for i in idx]
        mean_len = sum(lens) / len(lens)
        std_len = (sum((x - mean_len) ** 2 for x in lens) / len(lens)) ** 0.5 if len(lens) > 1 else 1.0

        for i in idx:
            z = (len(completions[i][0]['content']) - mean_len) / (std_len + 1e-6)
            # Reward shorter completions (negative z) and penalize longer ones
            scores[i] = -0.5 * z
    return scores

