def medmcqa_group_majority_bonus(prompts, completions, answer, **kwargs):
    groups = {}
    for i, p in enumerate(prompts):
        groups.setdefault(str(p[-1]['content']), []).append(i)

    scores = [0.0] * len(completions)
    for idx in groups.values():
        if len(idx) < 2:
            continue
        preds = [extract_solution(completions[i][0]['content']) for i in idx]
        valid_preds = [p for p in preds if p]
        if not valid_preds:
            continue

        # Count frequencies
        freq = {}
        for p in valid_preds:
            freq[p] = freq.get(p, 0) + 1

        majority = max(freq, key=freq.get)
        majority_count = freq[majority]
        consensus_ratio = majority_count / len(idx)

        for i in idx:
            pred = preds[i]
            if pred == majority:
                # Bonus scaled by consensus strength
                scores[i] = 1.0 + consensus_ratio
            else:
                scores[i] = -0.5 * (1.0 - consensus_ratio)
    return scores

