        valid_preds = [p for p in preds if p]
        if not valid_preds:
            continue

        unique_preds = set(valid_preds)
        if len(unique_preds) == 1:
            # Unanimous: small bonus for all
            for i in idx:
                scores[i] = 0.5
        else:
            # Divergent: penalize outliers
            freq = {}
            for p in valid_preds:
                freq[p] = freq.get(p, 0) + 1
            max_count = max(freq.values())

            for i in idx:
                pred = preds[i]
                if pred and freq.get(pred, 0) == max_count:
                    scores[i] = 0.0
                else:
                    scores[i] = -1.0
    return scores

